import assert from 'node:assert/strict';

import {
  buildTreeIndex,
  createInitialCollapsedNodeKeys,
  getHiddenRowsForCollapsedNodes,
  getTreeNodeKey,
  initializeTreeRows,
  toggleTreeNode,
  TreeRowMeta
} from '../src/components/report/preview/plugins/treeRender/utils';

function sorted(values: Iterable<number>) {
  return Array.from(values).sort((left, right) => left - right);
}

function createMockHot(rowCount = 8) {
  const hiddenRows = new Set<number>();
  const cellMeta = new Map<string, Record<string, unknown>>();
  const renderSnapshots: Array<Map<string, Record<string, unknown>>> = [];

  const hot = {
    renderCount: 0,
    countRows() {
      return rowCount;
    },
    getPlugin(name: string) {
      assert.equal(name, 'hiddenRows');
      return {
        showRows(rows: number[]) {
          rows.forEach((row) => hiddenRows.delete(row));
        },
        hideRows(rows: number[]) {
          rows.forEach((row) => hiddenRows.add(row));
        }
      };
    },
    setCellMeta(row: number, col: number, key: string, value: unknown) {
      const coord = `${row}:${col}`;
      const meta = cellMeta.get(coord) ?? {};
      meta[key] = value;
      cellMeta.set(coord, meta);
    },
    render() {
      this.renderCount += 1;
      renderSnapshots.push(
        new Map(
          Array.from(cellMeta, ([coord, meta]) => [
            coord,
            { ...meta, children: Array.isArray(meta.children) ? [...meta.children] : meta.children }
          ])
        )
      );
    }
  };

  return { hot, hiddenRows, cellMeta, renderSnapshots };
}

const treeRows: TreeRowMeta[] = [
  { row: 0, col: 0, children: [1, 4], treeParent: null, showLevel: 2 },
  { row: 1, col: 0, children: [2], treeParent: 0, showLevel: 2 },
  { row: 2, col: 0, children: [3], treeParent: 1, showLevel: 2 },
  // A second tree starts on the same row but in another column.
  { row: 0, col: 1, children: [5], treeParent: null, showLevel: 0 }
];

const index = buildTreeIndex(treeRows);
assert.deepEqual(index.roots.sort(), [getTreeNodeKey(0, 0), getTreeNodeKey(0, 1)].sort());
assert.equal(index.nodes.get(getTreeNodeKey(1, 0))?.parentKey, getTreeNodeKey(0, 0));
assert.equal(
  index.nodes.get(getTreeNodeKey(0, 1))?.parentKey,
  null,
  'nodes on the same row in different columns must remain separate trees'
);

const initialCollapsed = createInitialCollapsedNodeKeys(index);
assert.deepEqual(
  Array.from(initialCollapsed).sort(),
  [getTreeNodeKey(1, 0), getTreeNodeKey(2, 0), getTreeNodeKey(0, 1)].sort(),
  'showLevel must describe visible hierarchy levels, with one collapsing the root children'
);
assert.deepEqual(sorted(getHiddenRowsForCollapsedNodes(index, initialCollapsed)), [2, 3, 5]);

const levelRows = [0, 1, 2, 3].map((row) => ({
  row,
  col: 2,
  children: row < 3 ? [row + 1] : [],
  treeParent: row > 0 ? row - 1 : null
}));

[
  { showLevel: 0, hiddenRows: [1, 2, 3] },
  { showLevel: 1, hiddenRows: [1, 2, 3] },
  { showLevel: 2, hiddenRows: [2, 3] },
  { showLevel: 3, hiddenRows: [3] },
  { showLevel: 4, hiddenRows: [] }
].forEach(({ showLevel, hiddenRows: expectedHiddenRows }) => {
  const levelIndex = buildTreeIndex(levelRows.map((row) => ({ ...row, showLevel })));
  const collapsedKeys = createInitialCollapsedNodeKeys(levelIndex);
  assert.deepEqual(
    sorted(getHiddenRowsForCollapsedNodes(levelIndex, collapsedKeys)),
    expectedHiddenRows,
    `showLevel ${showLevel} must show exactly ${Math.max(1, showLevel)} hierarchy levels`
  );
});

const { hot, hiddenRows, cellMeta, renderSnapshots } = createMockHot();
initializeTreeRows(hot as any, treeRows);
assert.deepEqual(sorted(hiddenRows), [2, 3, 5]);
assert.equal(cellMeta.get('0:0')?.expanded, true);
assert.equal(cellMeta.get('1:0')?.expanded, false);
assert.equal(cellMeta.get('2:0')?.expanded, false);
assert.equal(cellMeta.get('0:1')?.expanded, false);
assert.deepEqual(cellMeta.get('0:0')?.children, [1, 4]);
assert.deepEqual(cellMeta.get('1:0')?.children, [2]);
assert.deepEqual(cellMeta.get('0:1')?.children, [5]);
assert.equal(hot.renderCount, 1, 'initialization must request a render for the first viewport');
assert.deepEqual(
  renderSnapshots[0].get('0:1'),
  { children: [5], expanded: false },
  'the row-0 collapsed node must be present before the initial render resumes'
);

assert.equal(toggleTreeNode(hot as any, 1, 0), true);
assert.deepEqual(sorted(hiddenRows), [3, 5], 'expanding a boundary branch shows rows until the next collapsed branch');
assert.equal(cellMeta.get('1:0')?.expanded, true);
assert.equal(hot.renderCount, 2);

toggleTreeNode(hot as any, 0, 0);
assert.deepEqual(sorted(hiddenRows), [1, 2, 3, 4, 5]);

toggleTreeNode(hot as any, 0, 0);
assert.deepEqual(sorted(hiddenRows), [3, 5], 'reopening a parent must preserve the expansion state of its descendants');

toggleTreeNode(hot as any, 0, 1);
assert.deepEqual(sorted(hiddenRows), [3], 'toggling one tree column must not use another column tree state');

assert.equal(toggleTreeNode(hot as any, 7, 0), false, 'unknown and leaf coordinates are ignored');
assert.equal(hot.renderCount, 5, 'initialization and successful node toggles rerender the table');

initializeTreeRows(hot as any, []);
assert.deepEqual(sorted(hiddenRows), [], 'loading an empty-tree sheet must clear rows hidden by the previous tree');

const treeCells = [
  { row: 0, col: 0, cellType: 'tree', treeLevel: 1 },
  { row: 1, col: 0, cellType: 'tree', treeLevel: 2 },
  { row: 2, col: 0, cellType: 'tree', treeLevel: 3 },
  { row: 3, col: 0, cellType: 'tree', treeLevel: 2 },
  { row: 4, col: 0, cellType: 'tree', treeLevel: 1 }
];

const fallbackTree = createMockHot();
initializeTreeRows(fallbackTree.hot as any, [], treeCells as any);
assert.deepEqual(sorted(fallbackTree.hiddenRows), [], 'tree cells without treeRows must remain initially visible');
assert.deepEqual(fallbackTree.cellMeta.get('0:0')?.children, [1, 3]);
assert.deepEqual(fallbackTree.cellMeta.get('1:0')?.children, [2]);
assert.equal(toggleTreeNode(fallbackTree.hot as any, 0, 0), true);
assert.deepEqual(sorted(fallbackTree.hiddenRows), [1, 2, 3]);

const legacyConfiguredTree = createMockHot(3);
initializeTreeRows(
  legacyConfiguredTree.hot as any,
  [
    { row: 0, col: 0, children: [1] },
    { row: 1, col: 0, children: [2], treeParent: 0 },
    { row: 2, col: 0, treeParent: 1 }
  ],
  treeCells.slice(0, 3) as any
);
assert.deepEqual(
  sorted(legacyConfiguredTree.hiddenRows),
  [1, 2],
  'configured treeRows without showLevel must retain the default one-level display'
);

const inferredLevelTree = buildTreeIndex([1, 2, 3, 2, 4, 1, 3].map((treeLevel, row) => ({ row, col: 0, treeLevel })));
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(1, 0))?.parentKey, getTreeNodeKey(0, 0));
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(2, 0))?.parentKey, getTreeNodeKey(1, 0));
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(3, 0))?.parentKey, getTreeNodeKey(0, 0));
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(4, 0))?.parentKey, getTreeNodeKey(3, 0));
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(5, 0))?.parentKey, null);
assert.equal(inferredLevelTree.nodes.get(getTreeNodeKey(6, 0))?.parentKey, getTreeNodeKey(5, 0));

console.log('tree preview collapse tests passed');

