export function handleLoadGlobalSettings(hot: HotTableClass, cells, globalSettings) {
  const mergeCells = filterCoveredMergeCells(getMergeCells(cells, globalSettings));
  const normalizedCells =
    cells
      ?.filter((c) => {
        const row = Number(c?.row);
        const col = Number(c?.col);
        if (!Number.isFinite(row) || !Number.isFinite(col)) return true;
        return !isCoveredCell(row, col, mergeCells);
      })
      .map((c) => {
        if (!c) return c;
        const { rowspan, colspan, hidden, mergeParent, ...cell } = c;
        if (!cell?.className) return cell;
        const next = stripNoOpBgFillFromClassName(cell.className);
        const className = next.trim() ? next : defaultClassName;
        return { ...cell, className };
      }) ?? cells;

  const aggregateClass = stripNoOpBgFillFromClassName(globalSettings?.className ?? '');
